 @page "/my-shipments"
 @attribute [Authorize]
 @inject IShipmentService ShipmentService
 @inject AuthenticationStateProvider AuthStateProvider

 <PageTitle>My Shipments</PageTitle>

 <h1>My Shipments</h1>

 @if (shipments is null)
 {
     <p><em>Loading your shipments...</em></p>
 }
 else if (!shipments.Any())
 {
     <p>You have no shipments associated with your account.</p>
 }
 else
 {
     <div class="mb-3">
         <strong>Showing @shipments.Count shipment(s)</strong>
     </div>

     <div class="row">
         @foreach (var shipment in shipments)
         {
             <div class="col-md-6 mb-3">
                 <div class="card">
                     <div class="card-body">
                         <h5 class="card-title">@shipment.TrackingNumber</h5>
                         <h6 class="card-subtitle mb-2 text-muted">@shipment.Description</h6>
                         <p class="card-text">
                             <strong>From:</strong> @shipment.Origin<br />
                             <strong>To:</strong> @shipment.Destination<br />
                             <strong>Status:</strong>
                             <span class="badge @GetStatusBadgeClass(shipment.Status)">@shipment.Status</span><br />
